import { MeshStandardNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec2, vec3, mix, smoothstep, sin, fract, dot, uniform } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const { Group, Mesh, BoxGeometry, PlaneGeometry, Color, PointLight, DoubleSide, SRGBColorSpace } = THREE;

  const colors = config?.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };

  const root = new Group();
  root.name = 'collection-card-1';
  const content = new Group();
  root.add(content);

  const disposables = [];
  const textures = [];
  const timelines = [];

  // ---- shared color uniforms ----
  const inkColor = uniform(new Color(colors.ink));
  const surfaceColor = uniform(new Color(colors.surface));
  const accentColor = uniform(new Color(colors.accent));

  // ---- opacity uniforms for entrance fade ----
  const fadeAmt = uniform(0);

  // ---- drop shadow depth plane (behind card, adds depth) ----
  const shadowGeo = new PlaneGeometry(2.9, 3.3);
  const shadowMat = new MeshBasicNodeMaterial({ transparent: true, side: DoubleSide });
  {
    const d = uv().sub(vec2(0.5, 0.5)).length();
    const falloff = smoothstep(0.55, 0.05, d);
    shadowMat.colorNode = vec3(0.0, 0.0, 0.0);
    shadowMat.opacityNode = falloff.mul(0.45).mul(fadeAmt);
  }
  const shadowMesh = new Mesh(shadowGeo, shadowMat);
  shadowMesh.position.set(0.04, -0.06, -0.12);
  content.add(shadowMesh);
  disposables.push(shadowGeo, shadowMat);

  // ---- machined-metal frame (subject body) ----
  const frameGeo = new BoxGeometry(2.6, 3.0, 0.09);
  const frameMat = new MeshStandardNodeMaterial({ transparent: true });
  {
    const g = uv().y;
    const gradient = mix(surfaceColor, inkColor, smoothstep(0.0, 1.0, g));
    const grain = fract(
      sin(dot(uv().mul(480.0), vec2(12.9898, 78.233))).mul(43758.5453)
    );
    const grainNode = grain.sub(0.5).mul(0.028);
    frameMat.colorNode = gradient.add(grainNode);
    frameMat.roughnessNode = uniform(0.58);
    frameMat.metalnessNode = uniform(0.4);
    frameMat.opacityNode = fadeAmt;
  }
  const frameMesh = new Mesh(frameGeo, frameMat);
  frameMesh.position.set(0, 0, 0);
  content.add(frameMesh);
  disposables.push(frameGeo, frameMat);

  // ---- accent signal strip (<=10% of frame area) ----
  const accentGeo = new PlaneGeometry(2.3, 0.055);
  const accentMat = new MeshStandardNodeMaterial({ transparent: true });
  accentMat.colorNode = accentColor;
  accentMat.emissiveNode = accentColor.mul(0.6);
  accentMat.roughnessNode = uniform(0.5);
  accentMat.metalnessNode = uniform(0.3);
  accentMat.opacityNode = fadeAmt;
  const accentMesh = new Mesh(accentGeo, accentMat);
  accentMesh.position.set(0, -1.32, 0.051);
  content.add(accentMesh);
  disposables.push(accentGeo, accentMat);

  // ---- image plane (foreground detail, unlit for true color) ----
  const imgGeo = new PlaneGeometry(2.28, 2.68);
  const imgMat = new MeshBasicNodeMaterial({ transparent: true });
  imgMat.colorNode = vec3(0.06, 0.06, 0.07);
  imgMat.opacityNode = fadeAmt;
  const imgMesh = new Mesh(imgGeo, imgMat);
  imgMesh.position.set(0, 0.1, 0.05);
  content.add(imgMesh);
  disposables.push(imgGeo, imgMat);

  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      if (SRGBColorSpace) tex.colorSpace = SRGBColorSpace;
      imgMat.map = tex;
      imgMat.needsUpdate = true;
      textures.push(tex);
    });
  }

  // ---- rim light (node-local, accent hued, capped) ----
  const rim = new PointLight(new Color(colors.accent), 0.8, 6.0);
  rim.position.set(1.6, 1.1, 1.4);
  content.add(rim);

  const keyFill = new PointLight(new Color(colors.paper), 0.4, 6.0);
  keyFill.position.set(-1.2, 1.6, 1.8);
  content.add(keyFill);

  // ---- motion: weighted-settle entrance ----
  content.position.y = -0.3;
  content.scale.setScalar(0.98);
  const entranceTl = gsap.timeline();
  entranceTl.to(fadeAmt, { value: 1, duration: 0.6, ease: 'power2.out' });
  entranceTl.to(
    content.position,
    { y: 0, duration: 0.9, ease: 'power4.out' },
    0
  );
  entranceTl.to(
    content.scale,
    { x: 1.03, y: 1.03, z: 1.03, duration: 0.5, ease: 'power3.out' },
    0
  );
  entranceTl.to(
    content.scale,
    { x: 1, y: 1, z: 1, duration: 0.4, ease: 'power2.out' },
    0.5
  );
  timelines.push(entranceTl);

  // ---- idle: single slow breathing transform (<=2%) ----
  const breatheTl = gsap.timeline({ repeat: -1, yoyo: true, delay: 1.5 });
  breatheTl.to(content.scale, {
    x: 1.02,
    y: 1.02,
    z: 1.02,
    duration: 3.2,
    ease: 'sine.inOut',
  });
  timelines.push(breatheTl);

  root.userData.handlers = {};

  root.userData.cleanup = () => {
    for (const tl of timelines) {
      tl.kill();
    }
    for (const tex of textures) {
      tex.dispose?.();
    }
    for (const res of disposables) {
      res.dispose?.();
    }
    rim.dispose?.();
    keyFill.dispose?.();
    content.remove(rim);
    content.remove(keyFill);
    root.clear();
  };

  return root;
}
